def criar_regras_iniciais(apps, schema_editor):
    Equipe = apps.get_model('helpdesk', 'Equipe')
    Regra = apps.get_model('helpdesk', 'RegraEncaminhamento')
    alias = schema_editor.connection.alias
    triagem = Equipe.objects.using(alias).get(triagem_padrao=True)
    destinos = {'Rede': 'Infraestrutura e Redes', 'Acessos': 'Identidades e Acessos',
                'Hardware': 'Suporte Especializado — N2', 'Software': 'Sistemas e Aplicações', 'Outros': None}
