        equipe = Equipe.objects.using(alias).filter(nome=nome).first() if nome else triagem
        # Nomes personalizados exigem revisão administrativa; não recriar equipes nem conceder vínculos.
        Regra.objects.using(alias).get_or_create(categoria=categoria, defaults={
            'equipe_id': equipe.pk if equipe else triagem.pk, 'ativa': equipe is not None,
        })


